'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useId, useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  QuoteIcon,
  StoreIcon,
} from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { SECTION, STORIES } from './data';
import { PersonTabs, tabIdOf } from './person-tabs';
import { PortraitStack } from './portrait-stack';
import { StoryQuote } from './story-quote';

const STORY_MS = 6500;

const ENTER: Transition = { duration: 0.45, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const QUOTE_VARIANTS: Variants = {
  enter: { opacity: 0, y: 8, filter: 'blur(4px)' },
  shown: { opacity: 1, y: 0, filter: 'blur(0px)', transition: ENTER },
  gone: { opacity: 0, y: -6, filter: 'blur(4px)', transition: EXIT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  shown: { opacity: 1, transition: ENTER },
  gone: { opacity: 0, transition: EXIT },
};

function variantsOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return QUOTE_VARIANTS;
}

function indexAfter(index: number) {
  const next = index + 1;
  return next % STORIES.length;
}

function indexBefore(index: number) {
  const shifted = index + STORIES.length;
  const previous = shifted - 1;
  return previous % STORIES.length;
}

/** The next person of every story, so a round ends on the first story and the loop shows no seam. */
const ROTATION = STORIES.map((_, index) => indexAfter(index));

function spokenStoryOf(index: number) {
  const { person } = STORIES[index];
  return `${person.name}, ${person.role} at ${person.company}`;
}

type Testimonials04Props = {
  /** Moves to the next story every few seconds until a person clicks, types or tabs into the block. */
  autoplay?: boolean;
};

export default function Testimonials04({
  autoplay = true,
}: Testimonials04Props) {
  const [activeIndex, setActiveIndex] = useState(0);
  const [isHovered, setIsHovered] = useState(false);
  const [message, setMessage] = useState('');
  const idBase = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const activeStory = STORIES[activeIndex];
  const panelId = `${idBase}-panel`;
  const activeTabId = tabIdOf(idBase, activeStory.id);
  const variants = variantsOf(shouldReduceMotion);
  const isFree = !isHovered;
  const isRotationEnabled = autoplay && isFree;

  const steps = ROTATION.map((index) => ({
    after: STORY_MS,
    run: () => setActiveIndex(index),
  }));
  const { ref } = useAutoplay<HTMLElement>(steps, {
    loopAfter: 0,
    isEnabled: isRotationEnabled,
  });

  function showByPerson(index: number) {
    setActiveIndex(index);
    setMessage(spokenStoryOf(index));
  }

  function pick(storyId: string) {
    const index = STORIES.findIndex((story) => story.id === storyId);
    showByPerson(index);
  }

  function showPrevious() {
    showByPerson(indexBefore(activeIndex));
  }

  function showNext() {
    showByPerson(indexAfter(activeIndex));
  }

  function holdUnderPointer(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType === 'mouse') {
      setIsHovered(true);
    }
  }

  function releasePointer() {
    setIsHovered(false);
  }

  return (
    <section
      ref={ref}
      onPointerEnter={holdUnderPointer}
      onPointerLeave={releasePointer}
      className='@container'
    >
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex max-w-2xl flex-col gap-3'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <StoreIcon className='size-4' />
            {SECTION.label}
          </p>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.lead}
          </p>
        </header>
        <div className='grid gap-6 @3xl:grid-cols-[minmax(0,2fr)_minmax(0,3fr)] @3xl:gap-12'>
          <PortraitStack stories={STORIES} activeId={activeStory.id} />
          <div className='flex min-w-0 flex-col gap-8 @3xl:justify-between @3xl:py-2'>
            <div className='flex flex-col gap-5'>
              <div className='flex items-center justify-between gap-3'>
                <QuoteIcon className='text-primary-ink size-7' />
                <Badge variant='secondary'>Sample quotes</Badge>
              </div>
              <div
                id={panelId}
                role='tabpanel'
                aria-labelledby={activeTabId}
                className='grid *:col-start-1 *:row-start-1'
              >
                {STORIES.map((story) => (
                  <div key={story.id} aria-hidden='true' className='invisible'>
                    <StoryQuote story={story} />
                  </div>
                ))}
                <AnimatePresence initial={false}>
                  <motion.div
                    key={activeStory.id}
                    variants={variants}
                    initial='enter'
                    animate='shown'
                    exit='gone'
                  >
                    <StoryQuote story={activeStory} />
                  </motion.div>
                </AnimatePresence>
              </div>
            </div>
            <div className='flex items-end gap-3'>
              <PersonTabs
                stories={STORIES}
                activeId={activeStory.id}
                tabIdBase={idBase}
                panelId={panelId}
                onPick={pick}
                className='min-w-0 flex-1'
              />
              <div className='flex shrink-0 items-center gap-1 pb-1'>
                <Button
                  type='button'
                  variant='outline'
                  size='icon-sm'
                  aria-label='Show the previous story'
                  onClick={showPrevious}
                >
                  <ChevronLeftIcon />
                </Button>
                <Button
                  type='button'
                  variant='outline'
                  size='icon-sm'
                  aria-label='Show the next story'
                  onClick={showNext}
                >
                  <ChevronRightIcon />
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import type { Story } from './data';

function layerToneOf(isActive: boolean) {
  if (isActive) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

type PortraitStackProps = {
  stories: readonly Story[];
  activeId: string;
};

/**
 * Every portrait is laid out at once and only the current one is opaque, so a change of person is
 * an opacity crossfade on the compositor and the frame never changes size.
 */
export function PortraitStack({ stories, activeId }: PortraitStackProps) {
  return (
    <div
      aria-hidden='true'
      className='relative aspect-[3/2] w-full @3xl:aspect-[4/5]'
    >
      {stories.map((story) => {
        const isActive = story.id === activeId;
        const { person } = story;

        return (
          <div
            key={story.id}
            className={cn(
              'absolute inset-0 transition-opacity duration-500 ease-(--ease-out-strong)',
              layerToneOf(isActive)
            )}
          >
            <Avatar seed={person.name} className='size-full rounded-2xl' />
            <span className='bg-card/90 hairline-ring ring-border dark:bg-popover/90 absolute start-3 bottom-3 flex max-w-[calc(100%-1.5rem)] items-center gap-2 rounded-lg py-1.5 ps-1.5 pe-2.5 text-xs font-medium shadow-[0_1px_2px_rgb(0_0_0/0.06)]'>
              <CompanyMark seed={person.company} />
              <span className='truncate'>{person.company}</span>
            </span>
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';

import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import type { Story } from './data';

export function tabIdOf(base: string, storyId: string) {
  return `${base}-tab-${storyId}`;
}

type Progress = 'past' | 'current' | 'ahead';

function progressOf(index: number, activeIndex: number): Progress {
  if (index === activeIndex) {
    return 'current';
  }
  if (index < activeIndex) {
    return 'past';
  }
  return 'ahead';
}

const FILL_CLASS: Record<Progress, string> = {
  past: 'scale-x-100 bg-foreground/30',
  current: 'scale-x-100 bg-primary',
  ahead: 'scale-x-0 bg-foreground/30',
};

function isStoryId(value: unknown, stories: readonly Story[]) {
  return stories.some((story) => story.id === value);
}

type PersonTabsProps = {
  stories: readonly Story[];
  activeId: string;
  tabIdBase: string;
  panelId: string;
  onPick: (storyId: string) => void;
  className?: string;
};

export function PersonTabs({
  stories,
  activeId,
  tabIdBase,
  panelId,
  onPick,
  className,
}: PersonTabsProps) {
  const activeIndex = stories.findIndex((story) => story.id === activeId);

  function pickTab(value: unknown) {
    if (isStoryId(value, stories)) {
      onPick(String(value));
    }
  }

  return (
    <TabsPrimitive.Root
      value={activeId}
      onValueChange={pickTab}
      className={className}
    >
      <TabsPrimitive.List
        activateOnFocus
        aria-label='Choose a customer'
        className='grid grid-cols-4 gap-2'
      >
        {stories.map((story, index) => {
          const { person } = story;
          const progress = progressOf(index, activeIndex);

          return (
            <TabsPrimitive.Tab
              key={story.id}
              value={story.id}
              id={tabIdOf(tabIdBase, story.id)}
              aria-controls={panelId}
              aria-label={`${person.name}, ${person.company}`}
              className='group/tab focus-visible:ring-ring/25 flex min-w-0 cursor-pointer flex-col gap-2.5 rounded-lg px-1 pt-1 pb-0.5 text-start outline-none focus-visible:ring-[3px]'
            >
              <span className='flex min-w-0 items-center gap-2'>
                <Avatar seed={person.name} className='size-6' />
                <span className='text-muted-foreground group-hover/tab:text-foreground group-data-active/tab:text-foreground hidden truncate text-[13px] font-medium transition-colors duration-150 @xl:block'>
                  {person.name}
                </span>
              </span>
              <span className='bg-foreground/10 relative h-0.5 overflow-hidden rounded-full'>
                <span
                  className={cn(
                    'absolute inset-0 origin-left rounded-full transition-[scale,background-color] duration-300 ease-(--ease-out-strong)',
                    FILL_CLASS[progress]
                  )}
                />
              </span>
            </TabsPrimitive.Tab>
          );
        })}
      </TabsPrimitive.List>
    </TabsPrimitive.Root>
  );
}

import { BrandTile } from '@/registry/ndeko/ui/brand-tile';

import type { QuotePart, Story } from './data';

function QuotePartView({ part }: { part: QuotePart }) {
  if (part.kind === 'brand') {
    return (
      <span className='whitespace-nowrap'>
        <BrandTile
          brand={part.brand}
          size='md'
          className='me-1.5 align-[-0.15em]'
        />
        {part.text}
      </span>
    );
  }
  return part.text;
}

export function StoryQuote({ story }: { story: Story }) {
  const { person } = story;

  return (
    <figure className='flex flex-col gap-6'>
      <blockquote className='text-xl leading-snug font-medium text-pretty @4xl:text-[1.75rem] @4xl:leading-[1.3]'>
        <p>
          {story.parts.map((part, index) => (
            <QuotePartView key={index} part={part} />
          ))}
        </p>
      </blockquote>
      <figcaption className='flex flex-col gap-0.5'>
        <span className='text-sm font-medium'>{person.name}</span>
        <span className='text-muted-foreground text-[13px]'>
          {person.role}, {person.company}
        </span>
      </figcaption>
    </figure>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type QuotePart =
  | { kind: 'text'; text: string }
  | { kind: 'brand'; brand: BrandSlug; text: string };

export type Person = {
  name: string;
  role: string;
  company: string;
};

export type Story = {
  id: string;
  parts: QuotePart[];
  person: Person;
};

export const SECTION = {
  label: 'Customer stories',
  title: 'Shops that stopped reordering by feel',
  lead: 'Stowly reads what sold and what is on the way, and tells you what will run out before it does.',
};

/** Invented people and companies. The quotes are samples written for this block. */
export const STORIES: Story[] = [
  {
    id: 'grace',
    parts: [
      {
        kind: 'text',
        text: 'We used to reorder on Sunday nights, by feel. Now Stowly tells us on Thursday what will run out next week, and it has been right often enough that we stopped checking twice.',
      },
    ],
    person: {
      name: 'Grace Mwangi',
      role: 'Operations lead',
      company: 'Pallet & Pine',
    },
  },
  {
    id: 'lukas',
    parts: [
      { kind: 'text', text: 'It reads our sales from ' },
      { kind: 'brand', brand: 'shopify', text: 'Shopify' },
      {
        kind: 'text',
        text: ' and the lead times of every supplier in one place. The reorder list is ready before I open the shop.',
      },
    ],
    person: {
      name: 'Lukas Brenner',
      role: 'Founder',
      company: 'Brenner Bikes',
    },
  },
  {
    id: 'nadia',
    parts: [
      {
        kind: 'text',
        text: 'The forecast explains itself. When it asks for twice the usual olive oil, it shows me the festival weekend it found in last year’s sales.',
      },
    ],
    person: {
      name: 'Nadia Haddad',
      role: 'Buyer',
      company: 'Cedar & Salt',
    },
  },
  {
    id: 'owen',
    parts: [
      { kind: 'text', text: 'Purchase orders go straight to ' },
      { kind: 'brand', brand: 'quickbooks', text: 'QuickBooks' },
      {
        kind: 'text',
        text: ', so closing the month is one check instead of an afternoon of matching receipts.',
      },
    ],
    person: {
      name: 'Owen Prescott',
      role: 'Finance manager',
      company: 'Northline Pharmacy',
    },
  },
];
